{"objective":"Integrate readablePaths into the mission manifest projection.","constraints":["Keep path confinement inside src/agent-tools.mjs and manifest projection inside src/mission-runtime.mjs.","Do not weaken writablePaths enforcement.","All existing tests must remain green.","Use structured refusals rather than throwing for a model's out-of-readable-scope action.","Prefer the admitted focus paths: src/mission-runtime.mjs"],"writablePaths":["src/mission-runtime.mjs"],"changed":[{"path":"src/mission-runtime.mjs","after":"import { randomUUID } from "node:crypto";
import { cpSync, existsSync, mkdirSync, mkdtempSync, readFileSync, renameSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { tmpdir } from "node:os";
import { createAgentTools, digest, territorySnapshot } from "./agent-tools.mjs";
import { dispatchBatch as defaultDispatch } from "./fabric-client.mjs";
import { runTestsCommand } from "./executor.mjs";
import { appendTrajectory, promotionReadout, recallTrajectories, trajectoryFingerprint } from "./trajectory-memory.mjs";

export const ACTION_SCHEMA = {
  type: "object",
  required: ["action", "args", "reason"],
  properties: {
    action: { type: "string", enum: ["list_files", "search", "read", "edit", "command", "test", "finish"] },
    args: { type: "object", additionalProperties: true },
    reason: { type: "string", minLength: 5, maxLength: 500 },
  },
  additionalProperties: false,
};

const SYSTEM = `You are an autonomous software worker operating an isolated copy of one admitted territory. Invoke exactly one tool per response using the contracted JSON. Available actions:
list_files {path?,max?}; search {query,path?}; read {path,startLine?,endLine?}; edit {path,blocks}; command {name}; test {}; finish {summary?}.
Include only the arguments used by the selected action. For edit, blocks must be exact SEARCH/REPLACE blocks: <<<<<<< SEARCH, exact old text, =======, replacement, >>>>>>> REPLACE. You have no shell. Inspect declared focus paths first, then edit as soon as enough evidence is available. Do not explore operational data records unless the objective names them. Make the smallest correct change. The host automatically runs the declared verification after every edit. Never claim success without a passing verification result.`;

function parseAction(record) {
  if (!record || typeof record.text !== "string") return null;
  let value;
  try { value = JSON.parse(record.text); } catch { return null; }
  const aliases = { read_file: "read", list_dir: "list_files", edit_file: "edit", run_test: "test", apply_patch: "edit" };
  if (typeof value.action === "string") return { action: aliases[value.action] || value.action, args: value.args && typeof value.args === "object" ? value.args : Object.fromEntries(Object.entries(value).filter(([key]) => !["action", "reason"].includes(key))), reason: value.reason || "provider selected this next tool move" };
  if (typeof value.command === "string") return { action: aliases[value.command] || value.command, args: Object.fromEntries(Object.entries(value).filter(([key]) => !["command", "reason"].includes(key))), reason: value.reason || "provider selected this next tool move" };
  for (const name of ["list_files", "list_dir", "search", "read", "read_file", "edit", "edit_file", "test", "run_test", "finish"]) {
    if (value[name] !== undefined) return { action: aliases[name] || name, args: value[name] && typeof value[name] === "object" ? value[name] : {}, reason: value.reason || "provider selected this next tool move" };
  }
  if (typeof value.path === "string") return { action: value.blocks !== undefined ? "edit" : "read", args: value, reason: value.blocks !== undefined ? "provider supplied a source edit" : "provider selected a source path to inspect" };
  return null;
}

function copyTerritory(source) {
  const parent = mkdtempSync(join(tmpdir(), "union-dev-actor-")), workspace = join(parent, "territory");
  cpSync(source, workspace, { recursive: true, filter: (path) => !path.split(/[\\/]/).some((part) => [".git", "node_modules", ".lake", "dist", "coverage"].includes(part)) });
  return { parent, workspace };
}

function actorPrompt(manifest, actor, snapshot, memories) {
  const recent = actor.observations.slice(-5).map((x, i) => `Observation ${i + 1}: ${x}`).join("\n");
  return [
    `OBJECTIVE: ${manifest.objective}`,
    manifest.constraints ? `CONSTRAINTS: ${manifest.constraints.join("; ")}` : "",
    manifest.focusPaths.length ? `FOCUS PATHS (inspect before anything else): ${manifest.focusPaths.join(", ")}` : "",
    manifest.writablePaths.length ? `WRITABLE PATHS (mechanically enforced): ${manifest.writablePaths.join(", ")}` : "",
    manifest.readablePaths.length ? `READABLE PATHS (mechanically enforced): ${manifest.readablePaths.join(", ")}` : "",
    `DECLARED VERIFICATION: ${manifest.verifyCommand}`,
    `OBJECTIVE ACCEPTANCE: ${manifest.acceptanceCommand}`,
    Object.keys(manifest.commands).length ? `ADMITTED COMMANDS: ${Object.entries(manifest.commands).map(([name, spec]) => `${name}: ${spec.description || spec.command}`).join("; ")}` : "No commands beyond test/acceptance are admitted.",
    `TERRITORY FILES (${snapshot.truncated ? "truncated" : "complete"}): ${snapshot.files.slice(0, 240).join(", ")}`,
    memories.length ? `RECALLED VERIFIED TRAJECTORIES: ${JSON.stringify(memories)}` : "",
    recent || "No tool observations yet. Begin by inspecting the territory.",
  ].filter(Boolean).join("\n\n").slice(-30000);
}

function jobFor(manifest, actor, snapshot, memories, round) {
  return {
    id: `${manifest.id}:actor:${actor.id}:round:${round}`,
    workType: manifest.workType,
    requiredCapabilities: manifest.requiredCapabilities,
    difficulty: manifest.difficulty ?? 0.55,
    maxTokens: manifest.maxTokens ?? 900,
    ...(actor.preferredEndpoint ? { preferEndpoints: [actor.preferredEndpoint] } : {}),
    messages: [{ role: "system", content: SYSTEM }, { role: "user", content: actorPrompt(manifest, actor, snapshot, memories) }],
    outputContract: manifest.enforceProviderSchema ? { format: "json", mode: "json_schema", schema: ACTION_SCHEMA } : { format: "json" },
  };
}

function integrateCandidate(source, candidate, verifyCommand, acceptanceCommand) {
  const backups = [];
  for (const change of candidate.changes) {
    const target = resolve(source, change.path);
    const currentExists = existsSync(target), current = currentExists ? readFileSync(target) : Buffer.alloc(0);
    if (currentExists !== change.before.existed || digest(current) !== change.before.digest) {
      return { integrated: false, classification: "protected-border", reason: `source changed since isolation: ${change.path}` };
    }
    backups.push({ target, existed: currentExists, bytes: current });
  }
  try {
    for (const change of candidate.changes) {
      const target = resolve(source, change.path), temporary = `${target}.union-dev-${process.pid}`;
      mkdirSync(dirname(target), { recursive: true });
      writeFileSync(temporary, change.after);
      renameSync(temporary, target);
    }
    const verification = runTestsCommand(source, verifyCommand);
    const acceptance = acceptanceCommand === verifyCommand ? verification : runTestsCommand(source, acceptanceCommand);
    if (verification.passed && acceptance.passed) return { integrated: true, classification: "repair", verification, acceptance };
    for (const backup of backups) backup.existed ? writeFileSync(backup.target, backup.bytes) : rmSync(backup.target, { force: true });
    return { integrated: false, classification: "repair-rejected", reason: "verification or objective acceptance failed after integration", verification, acceptance };
  } catch (error) {
    for (const backup of backups) backup.existed ? writeFileSync(backup.target, backup.bytes) : rmSync(backup.target, { force: true });
    return { integrated: false, classification: "repair-rejected", reason: error.message };
  }
}

export async function runMission(input, {
  dispatch = defaultDispatch,
  ledgerRoot,
  keepWorkspaces = false,
  onEvent = () => {},
  reviewCandidate,
  signal,
} = {}) {
  const manifest = {
    id: input.id || `urn:ame:free-compute-dev:mission:${randomUUID()}`,
    objective: input.objective,
    taskClass: input.taskClass || null,
    focusPaths: Array.isArray(input.focusPaths) ? [...new Set(input.focusPaths.filter((value) => typeof value === "string" && value))].slice(0, 32) : [],
    writablePaths: Array.isArray(input.writablePaths) ? [...new Set(input.writablePaths.filter((value) => typeof value === "string" && value))].slice(0, 32) : [],
    readablePaths: Array.isArray(input.readablePaths) ? [...new Set(input.readablePaths.filter((value) => typeof value === "string" && value))].slice(0, 32) : [],
    workType: typeof input.workType === "string" && input.workType ? input.workType : "classification",
    requiredCapabilities: Array.isArray(input.requiredCapabilities) && input.requiredCapabilities.length
      ? [...new Set(input.requiredCapabilities.filter((value) => typeof value === "string" && value))]
      : ["classification", input.enforceProviderSchema === true ? "json-schema-output" : "json-output"],
    territory: resolve(input.territory),
    verifyCommand: input.verifyCommand,
    acceptanceCommand: input.acceptanceCommand || input.verifyCommand,
    commands: input.commands || {},
    constraints: input.constraints || [],
    actors: Math.max(1, Math.min(Number(input.actors) || 3, 24)),
    maxRounds: Math.max(1, Math.min(Number(input.maxRounds) || 8, 30)),
    apply: input.apply === true,
    difficulty: input.difficulty,
    maxTokens: input.maxTokens,
    fabricAttempts: Math.max(1, Math.min(Number(input.fabricAttempts) || 4, 8)),
    fabricConcurrency: Math.max(1, Math.min(Number(input.fabricConcurrency) || input.actors || 3, 64)),
    enforceProviderSchema: input.enforceProviderSchema === true,
    providerTimeoutMs: input.providerTimeoutMs == null ? null : Math.max(1000, Math.min(Number(input.providerTimeoutMs), 300000)),
    endpointShards: Array.isArray(input.endpointShards) ? input.endpointShards.filter((value) => typeof value === "string" && value) : [],
    minVerifiedCandidates: Math.max(1, Math.min(Number(input.minVerifiedCandidates) || 1, 24)),
    maxConsecutiveRefusals: Math.max(1, Math.min(Number(input.maxConsecutiveRefusals) || 3, 10)),
  };
  if (!manifest.objective || !manifest.verifyCommand || !existsSync(manifest.territory)) throw new Error("mission requires objective, existing territory, and verifyCommand");
  const startedAt = new Date().toISOString(), snapshot = territorySnapshot(manifest.territory);
  const baselineVerification = runTestsCommand(manifest.territory, manifest.verifyCommand);
  const memories = recallTrajectories(manifest.objective, { ledgerRoot });
  onEvent({ type: "mission-started", missionId: manifest.id, startedAt, actors: manifest.actors, filesObserved: snapshot.files.length, baselineVerificationPassed: baselineVerification.passed });
  const actors = Array.from({ length: manifest.actors }, (_, index) => {
    const isolated = copyTerritory(manifest.territory);
    return { id: index + 1, preferredEndpoint: manifest.endpointShards[index % Math.max(1, manifest.endpointShards.length)] || null, ...isolated, tools: createAgentTools({ root: isolated.workspace, verifyCommand: manifest.verifyCommand, acceptanceCommand: manifest.acceptanceCommand, commands: manifest.commands, writablePaths: manifest.writablePaths }), observations: [], actions: [], providers: [], status: "active", completions: 0, consecutiveRefusals: 0 };
  });
  let rounds = 0, attempts = 0;
  try {
    for (let round = 1; round <= manifest.maxRounds && actors.some((a) => a.status === "active"); round += 1) {
      if (signal?.aborted) break;
      rounds = round;
      const active = actors.filter((a) => a.status === "active");
      onEvent({ type: "inference-wave-started", missionId: manifest.id, round, actors: active.map((a) => a.id) });
      const records = await dispatch(active.map((actor) => jobFor(manifest, actor, snapshot, memories, round)), { concurrency: manifest.fabricConcurrency, attempts: manifest.fabricAttempts, timeoutMs: manifest.providerTimeoutMs });
      onEvent({ type: "inference-wave-settled", missionId: manifest.id, round, records: records.map((record) => ({ id: record.id, endpoint: record.endpoint || null, refusal: record.refusal?.type || null, attempts: (record.attempts || []).map((attempt) => ({ endpoint: attempt.endpoint, outcome: attempt.outcome, reason: attempt.reason || null, latencyMs: attempt.latencyMs })) })) });
      const byId = new Map(records.map((record) => [record.id, record]));
      for (const actor of active) {
        const record = byId.get(`${manifest.id}:actor:${actor.id}:round:${round}`);
        attempts += record?.attempts?.length || 0;
        const action = parseAction(record);
        if (!action) {
          actor.observations.push(`Inference refusal or invalid action: ${record?.refusal?.type || "no result"}`);
          actor.consecutiveRefusals += 1;
          if (actor.consecutiveRefusals >= manifest.maxConsecutiveRefusals) {
            actor.status = "refused";
            onEvent({ type: "actor-circuit-opened", missionId: manifest.id, round, actorId: actor.id, consecutiveRefusals: actor.consecutiveRefusals });
          }
          continue;
        }
        actor.consecutiveRefusals = 0;
        actor.completions += 1;
        actor.actions.push(action);
        actor.providers.push(record?.endpoint || record?.attempts?.find((attempt) => attempt.outcome === "completion")?.endpoint || null);
        let observation;
        try { observation = actor.tools.execute(action); } catch (error) { observation = JSON.stringify({ error: error.message }); }
        actor.observations.push(observation);
        onEvent({ type: "actor-action-settled", missionId: manifest.id, round, actorId: actor.id, action: action.action, endpoint: record?.endpoint || null });
        const verdict = (() => { try { return JSON.parse(observation); } catch { return null; } })();
        if (actor.tools.changed.size > 0 && verdict?.verification?.passed === true && verdict?.acceptance?.passed === true) actor.status = "verified";
        else if (action.action === "finish" && actor.tools.changed.size === 0) actor.observations.push("Finish refused: no repository change was produced.");
      }
      if (actors.filter((actor) => actor.status === "verified").length >= manifest.minVerifiedCandidates) {
        onEvent({ type: "candidate-quorum-reached", missionId: manifest.id, round, verifiedCandidates: actors.filter((actor) => actor.status === "verified").length });
        break;
      }
    }
    const candidates = actors.filter((a) => a.status === "verified").map((actor) => ({
      actorId: actor.id,
      changes: actor.tools.changes(),
      actions: actor.actions,
      observations: actor.observations,
      completions: actor.completions,
      providers: actor.providers,
    })).sort((a, b) => a.changes.reduce((n, x) => n + x.changedBytes, 0) - b.changes.reduce((n, x) => n + x.changedBytes, 0));
    const selected = candidates[0] || null;
    let semanticReview = { type: "SemanticAcceptanceNotRequired", accepted: true };
    if (selected && reviewCandidate) {
      try { semanticReview = await reviewCandidate({ manifest, candidate: selected }); }
      catch (error) { semanticReview = { type: "IndependentSemanticAcceptance", accepted: false, error: error.message }; }
    }
    const candidateAccepted = Boolean(selected) && semanticReview.accepted === true;
    const integration = candidateAccepted && manifest.apply
      ? integrateCandidate(manifest.territory, selected, manifest.verifyCommand, manifest.acceptanceCommand)
      : { integrated: false, classification: selected ? (candidateAccepted ? "verified-candidate" : "semantic-review-rejected") : "unresolved" };
    const finishedAt = new Date().toISOString();
    const outcome = {
      verified: candidateAccepted,
      candidateVerified: Boolean(selected),
      integrated: integration.integrated,
      classification: integration.classification,
      changedPaths: selected?.changes.map((x) => x.path) || [],
      selectedActorId: selected?.actorId || null,
      selectedActions: selected?.actions || [],
      trajectoryFingerprint: selected ? trajectoryFingerprint(selected.actions) : null,
      summary: selected
        ? candidateAccepted ? `actor ${selected.actorId} produced an execution- and semantic-acceptance-passing candidate` : `candidate failed independent semantic acceptance: ${semanticReview.reviews?.filter((review) => !review.accepted).map((review) => review.reason).join("; ") || semanticReview.error || "insufficient independent reviews"}`
        : "no actor produced a verification-passing candidate",
      semanticReview,
      integration,
    };
    const record = {
      type: "FreeComputeDevelopmentTrajectory",
      id: manifest.id,
      objective: manifest.objective,
      taskClass: manifest.taskClass,
      startedAt,
      finishedAt,
      territory: { path: manifest.territory, filesObserved: snapshot.files.length, baselineVerificationPassed: baselineVerification.passed },
      outcome,
      metrics: {
        actors: manifest.actors,
        rounds,
        inferenceAttempts: attempts,
        usefulCompletions: actors.reduce((n, a) => n + a.completions, 0),
        verifiedCandidates: candidates.length,
        directInteractiveModelCalls: 0,
      },
      actors: actors.map((a) => ({ id: a.id, status: a.status, actions: a.actions, providers: a.providers, observations: a.observations })),
    };
    const ledgerPath = appendTrajectory(record, { ledgerRoot });
    onEvent({ type: "mission-settled", missionId: manifest.id, outcome, ledgerPath });
    return { ...record, ledgerPath, promotion: promotionReadout(manifest.taskClass, { ledgerRoot }) };
  } finally {
    if (!keepWorkspaces) for (const actor of actors) rmSync(actor.parent, { recursive: true, force: true });
  }
}
